import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

@DisplayName("120/112_maximum_subarray")
class SolutionTest {

    @Test
    void shouldFindMaximumSubarraySum() {

        Completed solution = new Completed();

        assertEquals(
            6,
            solution.maxSubArray(new int[]{-2, 1, -3, 4, -1, 2, 1, -5, 4})
        );
    }

    @Test
    void shouldHandleSingleElement() {

        Completed solution = new Completed();

        assertEquals(1, solution.maxSubArray(new int[]{1}));
    }

    @Test
    void shouldSumEntireArrayWhenAllPositive() {

        Completed solution = new Completed();

        assertEquals(
            23,
            solution.maxSubArray(new int[]{5, 4, -1, 7, 8})
        );
    }

    @Test
    void shouldReturnLargestNegativeWhenAllNegative() {

        Completed solution = new Completed();

        assertEquals(
            -1,
            solution.maxSubArray(new int[]{-5, -2, -1, -3})
        );
    }
}
